import asyncio
from playwright.async_api import async_playwright
res=[]
def ok(n,c,x=''): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n+('' if c else f' — {x}'))
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={'width':390,'height':844},device_scale_factor=2,locale='th-TH'); pg=await ctx.new_page()
        await pg.goto('http://127.0.0.1:8765/index.html'); await pg.wait_for_selector('#v0.on .pimg.ok'); await pg.wait_for_timeout(600)
        dim=lambda sel: pg.eval_on_selector(sel,'e=>{const r=e.getBoundingClientRect();return [Math.round(r.width*10)/10,Math.round(r.height*10)/10]}')
        cs=lambda sel,prop: pg.eval_on_selector(sel,f'e=>getComputedStyle(e).{prop}')
        # --- reference values from the demo stylesheet
        ok('header button 37x37', await dim('#hdr .hbtn')==[37,37], await dim('#hdr .hbtn'))
        ok('header avatar 37x37', await dim('#hdr .avb')==[37,37])
        ok('ONLINE badge green #30c054', await cs('.badge','backgroundColor')=='rgb(48, 192, 84)')
        ok('header bg #303891', await cs('#hdr','backgroundColor')=='rgb(48, 56, 145)')
        ok('card aspect 856:540', abs((lambda d:d[0]/d[1])(await dim('.card3d'))-856/540)<0.02)
        ok('3 quick-action buttons (30px circles + pill)', await pg.locator('#v0 .qa button').count()==3 and await dim('.qa .rb')==[30,30])
        ok('4 service circles 62px', await pg.locator('#v0 .grid .tile').count()==4 and await dim('.tile .ic')==[62,62], await dim('.tile .ic'))
        ok('service circle colour #f0eff8', await cs('.tile .ic','backgroundColor')=='rgb(240, 239, 248)')
        ok('panel radius 22px', (await cs('#v0 .pn','borderTopLeftRadius'))=='22px')
        bw=await dim('.bn:nth-child(2)'); ok('banner ratio ~4.3:1, 79% of screen wide', abs(bw[0]/bw[1]-1064/248)<0.05 and abs(bw[0]-308)<3, bw)
        bl=await pg.eval_on_selector('.bn:nth-child(2)','e=>Math.round(e.getBoundingClientRect().left)'); ok('active banner centred', abs(bl-41)<=3, bl)
        ok('neighbour banners peek on both sides', await pg.eval_on_selector('.bn:nth-child(1)','e=>e.getBoundingClientRect().right>8') and await pg.eval_on_selector('.bn:nth-child(3)','e=>e.getBoundingClientRect().left<382'))
        ok('2 banner dots, active 38px', await pg.locator('#dt i').count()==2 and (await dim('#dt i.a'))[0]==38)
        ok('announcement title 15.5px / card radius 14', await cs('.nc b','fontSize')=='15.5px' and await cs('.nc','borderTopLeftRadius')=='14px')
        ok('5 nav items', await pg.locator('#nv .ni').count()==5)
        ok('scan button 68px raised', await dim('.sb')==[68,68] and (await pg.eval_on_selector('.sb','e=>e.getBoundingClientRect().top'))<(await pg.eval_on_selector('#nv','e=>e.getBoundingClientRect().top')))
        ok('nav label 11px #5e5e5e', await cs('.ni:nth-child(2)','fontSize')=='11px' and await cs('.ni:nth-child(2)','color')=='rgb(94, 94, 94)')
        ok('active nav #2f54d9', await cs('.ni.on','color')=='rgb(47, 84, 217)')
        ok('chat button 52px, white', await dim('#fab')==[52,52] and await cs('#fab','backgroundColor')=='rgb(255, 255, 255)')
        ok('font stack starts with Prompt', (await cs('body','fontFamily')).startswith('Prompt'))
        # --- card interactions
        t0=await pg.get_attribute('#v0 .face .pimg','alt')
        bx=await pg.locator('#v0 .flipw').bounding_box(); y=bx['y']+bx['height']/2
        await pg.mouse.move(bx['x']+bx['width']*0.8,y); await pg.mouse.down(); await pg.mouse.move(bx['x']+bx['width']*0.2,y,steps=6); await pg.mouse.up(); await pg.wait_for_timeout(500)
        t1=await pg.get_attribute('#v0 .face .pimg','alt'); ok('swipe on card switches document (no arrow buttons)', t1!=t0 and await pg.locator('#v0 .flipw .pg').count()==0, (t0,t1))
        await pg.mouse.move(bx['x']+bx['width']*0.2,y); await pg.mouse.down(); await pg.mouse.move(bx['x']+bx['width']*0.8,y,steps=6); await pg.mouse.up(); await pg.wait_for_timeout(500)
        ok('swipe back returns to first document, card not flipped by swipe', await pg.get_attribute('#v0 .face .pimg','alt')==t0 and await pg.locator('.card3d.f').count()==0)
        await pg.wait_for_selector('#v0 .pimg.ok'); await pg.wait_for_timeout(500)
        card='#v0 .card3d'; hasf=lambda: pg.eval_on_selector(card,'e=>e.classList.contains("f")')
        ok('no separate switch on the card (only card tap + 3 round buttons)', await pg.locator('#v0 .flipw button.pg').count()==0 and await pg.locator('#v0 .scene .seg, #v0 .scene .sw').count()==0)
        ok('starts on front', not await hasf())
        await pg.click(card,position={'x':120,'y':80}); await pg.wait_for_timeout(300); ok('tap card -> flips to back', await hasf())
        ok('3D flip duration 1.4s', await pg.eval_on_selector(card,'e=>getComputedStyle(e).transitionDuration')=='1.4s')
        await pg.click(card,position={'x':120,'y':80}); await pg.wait_for_timeout(300); ok('tap again -> back to front', not await hasf())
        await pg.click(card,position={'x':120,'y':80}); await pg.wait_for_timeout(1600)
        await pg.click('.qa .pill'); await pg.wait_for_selector('#vwr.on [data-vimg][src]'); await pg.wait_for_timeout(500); await pg.screenshot(path='shots/60-expanded-back.png')
        ok('expand opens overlay on the SAME side (back)', await pg.eval_on_selector('#vflip','e=>e.classList.contains("f")'))
        bx=await pg.eval_on_selector('#vbox','e=>{const r=e.getBoundingClientRect();return [r.width,r.height]}'); ok('card is large & rotated to landscape on portrait phone', bx[1]>bx[0] and bx[1]>430, bx)
        ok('overlay has back + flip (+ rotate) buttons', await pg.locator('#vwr [data-act=view-close]').count()==1 and await pg.locator('#vwr [data-act=view-flip]').count()==1)
        ok('both sides loaded independently', await pg.locator('#vwr [data-vimg]').count()==2)
        await pg.click('#vwr [data-act=view-flip]'); await pg.wait_for_timeout(300); ok('flip button inside preview -> front', not await pg.eval_on_selector('#vflip','e=>e.classList.contains("f")'))
        await pg.click('#vwr [data-act=view-close]'); await pg.wait_for_timeout(800)
        ok('close returns home; side stays in sync (front)', await pg.locator('#vwr.on').count()==0 and not await hasf() and await pg.locator('#v0.on').count()==1)
        ok('home still shows both images (not overwritten)', await pg.locator('#v0 .pimg').count()==2)
        # header identical on every tab, banner/ fab only on home
        for i in (2,3,4,5):
            await pg.click(f'.ni:nth-child({i})'); await pg.wait_for_timeout(450)
            ok(f'tab {i}: same profile header', 'ONLINE' in await pg.inner_text('#hdr') and await dim('#hdr .hbtn')==[37,37])
        ok('chat button hidden off-home', not await pg.is_visible('#fab'))
        # details page: own notes, validation, persistence
        await pg.click('.ni:nth-child(2)'); await pg.wait_for_selector('#v1 .dl'); await pg.click('#v1 .dl >> nth=0'); await pg.wait_for_selector('#sh.on'); await pg.click('#sh [data-act=det-open]'); await pg.wait_for_selector('#dp.on .pf-card'); await pg.click('#dp [data-act=det-edit]'); await pg.wait_for_selector('#dp.on .pf-info')
        await pg.fill('#m2','สมหญิง ตัวอย่างดี'); await pg.fill('#m3','NOTE-123'); await pg.select_option('[name=exd]','10'); await pg.select_option('[name=exm]',''); await pg.click('#dm button[type=submit]'); await pg.wait_for_timeout(300)
        ok('partial date rejected', 'ครบ' in await pg.inner_text('#dme'))
        await pg.select_option('[name=exm]','9'); await pg.select_option('[name=exy]',str(2031)); await pg.click('#dm button[type=submit]'); await pg.wait_for_timeout(500)
        ok('details saved & shown', 'NOTE-123' in await pg.inner_text('#dp .pf-idnum'))
        await pg.click('#dp [data-act=det-close].pf-x'); await pg.click('.ni:nth-child(2)'); await pg.wait_for_timeout(500)
        ok('expiry appears in library', 'หมดอายุ' in await pg.inner_text('#v1'))
        txt=await pg.evaluate('document.body.innerText'); ok('no verification claims', not any(w in txt for w in ['ยืนยันตัวตนแล้ว','verified','ตรวจสอบแล้ว']))
        await b.close()
    print(f'{sum(res)}/{len(res)} spec checks passed')
asyncio.run(main())
